// Lê o aviso que a UAZAPI mandou e devolve um item padronizado.
// Descarta grupo, canal, lista de transmissão e eventos que não são mensagem.
// Em mensagens "from me" o cliente continua sendo quem está no chatid.
const cfg = $('Configurações').first().json;
const req = $('Webhook').first().json;
const corpo = req.body || {};

const soDigitos = (v) => String(v ?? '').split('@')[0].replace(/[^0-9]/g, '');
const ignorar = (motivo, extra = {}) => [{ json: { tipo: 'ignorar', motivo, ...extra } }];

const evento = String(corpo.EventType || corpo.event || 'messages').toLowerCase();
if (evento !== 'messages') return ignorar('evento_' + evento);

const bruto = corpo.message ?? corpo.data ?? null;
const m = Array.isArray(bruto) ? bruto[0] : bruto;
if (!m || typeof m !== 'object') return ignorar('sem_mensagem');
const chat = (corpo.chat && typeof corpo.chat === 'object') ? corpo.chat : {};

const chatid = String(m.chatid || chat.wa_chatid || '');
if (m.isGroup === true || /@(g\.us|newsletter|broadcast)/.test(chatid)) return ignorar('grupo_ou_canal');

const ehEco = m.fromMe === true;
const clienteId = soDigitos(chatid) || (ehEco ? '' : soDigitos(m.sender));
if (!clienteId) return ignorar('sem_cliente');

const permitidos = String(cfg.numerosPermitidos || '').split(/[,;\s]+/).map(soDigitos).filter(Boolean);
const foraDaLista = permitidos.length > 0 && !permitidos.includes(clienteId);
if (foraDaLista) return ignorar('fora_da_lista_de_teste', { encaminhar: true, clienteId });

const tipoBruto = String(m.messageType || m.type || '').toLowerCase();
if (tipoBruto.includes('reaction') || tipoBruto.includes('protocol') || tipoBruto.includes('revoke')) {
  return ignorar('reacao_ou_apagada');
}

const mid = String(m.messageid || m.id || `${clienteId}-${m.messageTimestamp || Date.now()}`);
let texto = String(m.text || m.content?.text || (typeof m.content === 'string' ? m.content : '') || '').trim();

let tipo = 'texto';
if (ehEco) tipo = 'eco';
else if (tipoBruto.includes('audio') || tipoBruto.includes('ptt')) tipo = 'audio';
else if (tipoBruto.includes('image')) tipo = 'imagem';

if (!ehEco) {
  const complemento = texto ? ' ' + texto : '';
  if (tipoBruto.includes('sticker')) texto = '[O cliente enviou uma figurinha]';
  else if (tipoBruto.includes('video')) texto = '[O cliente enviou um vídeo, que não consigo assistir]' + complemento;
  else if (tipoBruto.includes('document')) texto = '[O cliente enviou um arquivo, que não consigo abrir]' + complemento;
  else if (tipoBruto.includes('location')) texto = '[O cliente enviou uma localização]' + complemento;
  else if (tipoBruto.includes('contact')) texto = '[O cliente enviou um contato]' + complemento;
  if (tipo === 'texto' && !texto) texto = '[O cliente enviou uma mensagem sem texto]';
  texto = texto.slice(0, 3000);
}

const nome = [chat.lead_fullName, chat.lead_name, chat.name, chat.wa_name, chat.wa_contactName, ehEco ? '' : m.senderName]
  .map(v => String(v ?? '').trim()).find(Boolean) || '';

const comandoVoltar = String(cfg.comandoVoltarMaya || '#maya').toLowerCase().trim();
const ttlPausa = Math.max(60, Math.round(Number(cfg.horasPausaHumano || 6) * 3600));

return [{
  json: {
    tipo,
    clienteId,
    mid,
    texto,
    nome,
    tipoMensagem: tipoBruto,
    enviadaPelaApi: m.wasSentByApi === true,
    comando: ehEco && comandoVoltar && texto.toLowerCase().includes(comandoVoltar) ? 'liberar' : '',
    ttlPausa,
    chaveMid: `wa:mid:${mid}`,
    chaveMarcaMaya: `wa:maya_mid:${mid}`,
    chaveMayaEnviando: `wa:maya_enviando:${clienteId}`,
    chaveHumano: `wa:humano:${clienteId}`,
    chaveRate: `wa:rate:${clienteId}`,
    chaveBuffer: `wa:buffer:${clienteId}`,
    chaveUltima: `wa:ultima:${clienteId}`,
    chaveMemoria: `wa:memoria:${clienteId}`,
    chaveLead: `wa:lead:${clienteId}`
  }
}];

// Junta as mensagens agrupadas do cliente e monta o contexto que a Maya recebe
// (hora em Brasília, se a equipe está no horário e o nome do cliente).
const cfg = $('Configurações').first().json;
const ev = $('Separar Eventos').item.json;
const bruto = $('Ler Mensagens Agrupadas').item.json.buffer;

let partes = Array.isArray(bruto) ? bruto : (bruto ? [bruto] : []);
partes = partes.map(p => String(p).trim()).filter(Boolean);
if (!partes.length) partes = [ev.texto];

const agora = DateTime.now().setZone('America/Sao_Paulo').setLocale('pt-BR');
const dentroHorario = agora.hour >= Number(cfg.horaAbre ?? 7) && agora.hour < Number(cfg.horaFecha ?? 23);

return {
  json: {
    clienteId: ev.clienteId,
    mid: ev.mid,
    nome: ev.nome,
    chaveMemoria: ev.chaveMemoria,
    chaveHumano: ev.chaveHumano,
    chaveLead: ev.chaveLead,
    chaveMayaEnviando: ev.chaveMayaEnviando,
    ttlPausa: ev.ttlPausa,
    mensagemCliente: partes.join('\n'),
    dataHora: agora.toFormat("cccc, dd/LL/yyyy 'às' HH:mm"),
    dentroHorario
  }
};

